from decision_progress import UniqueLoader

valid={
 'explicit override':'base: &b {owner: A, state: open}\nrow: {<<: *b, owner: B}\n',
 'merge list precedence':'a: &a {x: 1, y: 1}\nb: &b {x: 2, z: 2}\nrow: {<<: [*a, *b]}\n',
 'merge list with override':'a: &a {x: 1}\nb: &b {x: 2}\nrow: {<<: [*a, *b], x: 3}\n',
 'nested inherited defaults':'a: &a {x: 1, y: 2}\nb: &b {<<: *a, x: 3}\nrow: {<<: *b, y: 4}\n',
 'shared nested anchor reused':'a: &a {x: 1}\nb: &b {<<: *a, y: 2}\nrows: [{<<: *b, x: 3}, {<<: *b, y: 4}]\n',
 'repeated same merge source':'base: &b {x: 1}\nrow: {<<: [*b, *b]}\n',
 'quoted merge-looking ordinary key':'row: {"<<": data, x: 1}\n',
}
for name,raw in valid.items():
    expected=yaml.safe_load(raw)
    actual=yaml.load(raw,Loader=UniqueLoader)
    assert actual==expected,(name,actual,expected)
    print('PASS valid:',name)

invalid={
 'direct duplicate':'row: {history: [old], history: []}\n',
 'duplicate alongside merge':'base: &b {x: 1}\nrow: {<<: *b, history: [old], history: []}\n',
 'duplicate inside inherited source':'base: &b {history: [old], history: []}\nrow: {<<: *b}\n',
 'inherited duplicate explicitly overridden':'base: &b {history: [old], history: []}\nrow: {<<: *b, history: [new]}\n',
 'duplicate within nested inherited source':'a: &a {x: 1, x: 2}\nb: &b {<<: *a}\nrow: {<<: *b}\n',
 'duplicate within second merge-list source':'a: &a {x: 1}\nb: &b {history: [old], history: []}\nrow: {<<: [*a, *b]}\n',
 'quoted versus plain duplicate':'row: {history: [old], "history": []}\n',
 'equivalent typed keys':'row: {true: one, 1: two}\n',
}
for name,raw in invalid.items():
    try: yaml.load(raw,Loader=UniqueLoader)
    except ValueError as exc: assert 'duplicate YAML key' in str(exc),(name,exc)
    else: raise AssertionError('duplicate bypass: '+name)
    print('PASS rejects:',name)

